# Perform BFS from node '67c6a1e7ce' to find nodes at exactly depth 16
from collections import deque

start_node = '67c6a1e7ce'
target_depth = 16

# BFS tracking depth
queue = deque([(start_node, 0)])  # (node, depth)
visited = {start_node}
nodes_at_depth = {i: set() for i in range(target_depth + 1)}

while queue:
    node, depth = queue.popleft()

    if depth > target_depth:
        break

    if depth > 0:  # Don't include start node
        nodes_at_depth[depth].add(node)

    if depth < target_depth:
        for neighbor in adj.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth + 1))

# Get nodes at exactly depth 16
result_nodes = sorted(nodes_at_depth[target_depth])
print(f"Nodes at depth 16: {result_nodes}")
print(f"Count: {len(result_nodes)}")

# Let's also check intermediate depths to verify
for d in [1, 2, 4, 8, 12, 15, 16]:
    print(f"Depth {d}: {len(nodes_at_depth[d])} nodes")

